import bisect

def histogram(edges, values):
    if len(edges) < 2:
        raise ValueError("edges must be a strictly increasing list with at least two numbers")
    for i in range(len(edges) - 1):
        if edges[i] >= edges[i + 1]:
            raise ValueError("edges must be a strictly increasing list with at least two numbers")

    n = len(edges) - 1
    counts = [0] * n

    for v in values:
        if v < edges[0] or v > edges[-1]:
            continue
        idx = bisect.bisect_right(edges, v) - 1
        if idx >= n:
            idx = n - 1
        counts[idx] += 1

    return counts
```

