def normalize(path: str) -> str:
    """Normalize an absolute POSIX-like path.

    - Rejects non-absolute paths with ValueError.
    - Collapses repeated '/'.
    - Ignores '.' components.
    - Resolves '..' without going above root.
    - Returns '/' for root.
    - Never returns a trailing slash elsewhere.
    - No filesystem access.
    """
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if not path.startswith('/'):
        raise ValueError(f"not an absolute path: {path!r}")

    parts = path.split('/')
    stack: list[str] = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # else: stay at root, ignore
        else:
            stack.append(part)

    if not stack:
        return '/'
    return '/' + '/'.join(stack)
```

