def pack(items, max_bytes):
    if not isinstance(max_bytes, int) or max_bytes < 1:
        raise ValueError("max_bytes must be an integer >= 1")

    if not items:
        return []

    for item in items:
        if len(item.encode("utf-8")) > max_bytes:
            raise ValueError(
                f"Item does not fit within max_bytes={max_bytes}"
            )

    result = []
    current_batch = []
    current_bytes = 0

    for item in items:
        item_bytes = len(item.encode("utf-8"))
        if current_bytes + item_bytes > max_bytes:
            result.append(current_batch)
            current_batch = []
            current_bytes = 0
        current_batch.append(item)
        current_bytes += item_bytes

    if current_batch:
        result.append(current_batch)

    return result
```

