import heapq


def order(deps):
    # Collect all nodes (keys and prerequisite-only nodes)
    nodes = set(deps.keys())
    for prereqs in deps.values():
        nodes.update(prereqs)

    # Build reverse dependency map and prerequisite counts
    prereq_count = {}
    dependents = {node: [] for node in nodes}

    for node in nodes:
        prereqs = deps.get(node, [])
        prereq_count[node] = len(prereqs)
        for p in prereqs:
            dependents[p].append(node)

    # Initialize min-heap with all nodes having zero prerequisites
    heap = [node for node in nodes if prereq_count[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dependent in dependents[node]:
            prereq_count[dependent] -= 1
            if prereq_count[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result
